mapper.select:
SELECT COUNT(*)
FROM mdm_material_ref
WHERE deleted = 0
    AND material_code = #{materialCode}
    AND tenant_code = #{tenantCode}

mapper.delete:
UPDATE mdm_material_ref
SET deleted = DATE_FORMAT(NOW(6), '%Y%m%d%H%i%s%m'), version = version + 1
WHERE deleted = 0
    AND material_code = #{materialCode}
    AND biz_type = #{bizType}
    AND biz_code = #{bizCode}
    AND tenant_code = #{tenantCode}
